const { test, expect } = require('@playwright/test');
const path = require('path');
const { openApp, PROFILE } = require('./helpers');

// The import pipeline is the most destructive code in the app — it rewrites or merges a user's
// whole workspace — and had no coverage at all. These run the real path: a real .xlsx through the
// real file input, the real detector, the real commit.
//
// Fixtures are generated by tests/fixtures/make-workbooks.js from the genuine ScheduleHub v3.1
// starter template, so their sheet names and column headers are the ones the detectors key off
// rather than a guess at them.
const WORKBOOKS = path.join(__dirname, 'fixtures', 'workbooks');
const generated = (name) => path.join(WORKBOOKS, 'generated', name);

const NATIVE_OVERLAY = '#nsNativeImport';

async function openFresh(page) {
  await openApp(page, { profile: PROFILE, workspaceRow: null });
  await page.waitForFunction(() => !!document.getElementById('fi') && typeof XLSX === 'object');
  // The import path refuses to start until the bundled parser reports ready.
  await page.waitForFunction(() => {
    try { return requireExcelParserReady(); } catch (e) { return false; }
  }, null, { timeout: 30_000 });
}

async function uploadWorkbook(page, file) {
  await page.setInputFiles('#fi', file);
}

test('merged weekly agent rota keeps weekday labels and skips pre-skill weeks', async ({ page }) => {
  await openFresh(page);
  const bytes = await page.evaluate(() => {
    const dates = Array.from({ length: 21 }, (_, i) => new Date(2026, 10, 9 + i));
    const shifts = dates.map(date => date.getDay() % 6 ? '0600-1500' : 'RDO');
    const atWeeks = (...labels) => dates.map((_, i) => i % 7 ? '' : labels[i / 7]);
    const horizontal = [
      ['', ...dates.map(date => DOW[date.getDay()].slice(0, 3))],
      ['', ...dates],
      ['Alex', ...shifts],
      ['', ...atWeeks('Week 1', 'Week 2', 'Week 1')],
      ['Sam', ...atWeeks('-', 'Monday to Friday', '').slice(0, 14), ...shifts.slice(14)],
      ['', ...atWeeks('', '', 'Week 2')],
    ];
    const merges = ['A3:A4', 'A5:A6', 'B4:H4', 'I4:O4', 'P4:V4', 'B5:H6', 'I5:O6', 'P6:V6']
      .map(range => XLSX.utils.decode_range(range));
    const transpose = (grid) => grid[0].map((_, col) => grid.map(row => row[col]));
    const transposeCell = ({ r, c }) => ({ r: c, c: r });
    const wb = XLSX.utils.book_new();
    const overview = XLSX.utils.aoa_to_sheet([
      ['', 'WC', 'WC', 'WC', 'WC', 'WC'],
      ['', ...Array.from({ length: 5 }, (_, i) => new Date(2026, 10, 9 + i * 7))],
      ['Alex Example', 'Week 1', 'Week 2', 'Week 1', 'Week 2', 'Week 1'],
      ['Sam', '-', '-', 'Week 2', 'Week 1', 'Week 2'],
    ]);
    XLSX.utils.book_append_sheet(wb, overview, 'Overview');
    for (const vertical of [true, false]) {
      const ws = XLSX.utils.aoa_to_sheet(vertical ? transpose(horizontal) : horizontal);
      ws['!merges'] = vertical ? merges.map(({ s, e }) => ({ s: transposeCell(s), e: transposeCell(e) })) : merges;
      for (const addr of vertical ? ['C1', 'E1', 'A2'] : ['A3', 'A5', 'B1']) ws[addr].z = 'd-mmm';
      XLSX.utils.book_append_sheet(wb, ws, vertical ? 'Vertical' : 'Horizontal');
    }
    return Array.from(new Uint8Array(XLSX.write(wb, { bookType: 'xlsx', type: 'array' })));
  });
  await uploadWorkbook(page, { name: 'Agent View Nov 2026.xlsx', mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', buffer: Buffer.from(bytes) });
  const preview = page.locator('#parsePreviewOverlay');
  await expect(preview).toContainText('Load 33 entries');
  await expect(preview).toContainText('5 Mon-Fri shifts have unspecified hours.');
  await page.locator('#parseLoadBtn').click();
  await expect(preview).toHaveCount(0);
  const actual = await page.evaluate(() => {
    const sam = S.entries.filter(e => e.name === 'Sam').sort((a, b) => a.date - b.date);
    const weekday = sam[0];
    const roundTrip = _validateCanonicalScheduleEntries([weekday]).entries[0];
    return {
      people: [...new Set(S.entries.map(e => e.name))].sort(),
      entries: S.entries.length,
      untimed: sam.filter(isUntimedWeekdayShift).map(e => excKey(e.date)),
      working: !roundTrip.isOff,
      times: [roundTrip.ukS, roundTrip.ukE, roundTrip.saS, roundTrip.saE],
      label: [uD(roundTrip), sAD(roundTrip)],
      nextShift: [excKey(sam[5].date), sam[5].ukS],
      rdo: [sam.at(-1).raw, sam.at(-1).isOff],
    };
  });
  expect(actual).toEqual({
    people: ['Alex Example', 'Sam'],
    entries: 33,
    untimed: ['2026-11-16', '2026-11-17', '2026-11-18', '2026-11-19', '2026-11-20'],
    working: true,
    times: [null, null, null, null],
    label: ['Mon-Fri', 'Mon-Fri'],
    nextShift: ['2026-11-23', '06:00'],
    rdo: ['RDO', true],
  });
  await page.reload({ waitUntil: 'domcontentloaded' });
  await page.locator('#lcProjectPicker .lc-project-row').first().click();
  await expect.poll(() => page.evaluate(() => S.entries.filter(isUntimedWeekdayShift).map(sAD))).toEqual(Array(5).fill('Mon-Fri'));
});

test.describe('native SyncSheets import', () => {
  test('a ScheduleHub workbook is detected and previewed before anything is committed', async ({ page }) => {
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));

    const overlay = page.locator(NATIVE_OVERLAY);
    await expect(overlay).toBeVisible({ timeout: 40_000 });
    await expect(overlay).toContainText('ScheduleHub detected');
    await expect(overlay).toContainText('168');

    // Nothing has been written yet — the preview is a preview.
    expect(await page.evaluate(() => S.entries.length)).toBe(0);
    expect(await page.evaluate(() => nsListCanonicalProjects().length)).toBe(0);
  });

  test('confirming the import commits the rows and opens the workspace', async ({ page }) => {
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });

    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect(page.locator(NATIVE_OVERLAY)).toHaveCount(0);

    await expect.poll(() => page.evaluate(() => nsListCanonicalProjects().length), { timeout: 30_000 }).toBeGreaterThan(0);
    const projects = await page.evaluate(() => nsListCanonicalProjects().map((p) => ({ name: p.name, schedule: p.scheduleCount })));
    expect(projects[0].schedule).toBe(168);
    await expect(page.locator('#mv')).toBeVisible();
  });

  test('cancelling leaves the workspace untouched', async ({ page }) => {
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });

    await page.locator(NATIVE_OVERLAY).getByRole('button', { name: 'Cancel' }).click();
    await expect(page.locator(NATIVE_OVERLAY)).toHaveCount(0);
    expect(await page.evaluate(() => nsListCanonicalProjects().length)).toBe(0);
    expect(await page.evaluate(() => S.entries.length)).toBe(0);
    // Still on the landing screen, with the import route intact.
    await expect(page.locator('#mv')).toBeHidden();
  });

  test('an empty starter template is refused with an explanation, not a silent no-op', async ({ page }) => {
    // The blank v3.1 template has the right shape but no rows. It must not import as an empty
    // project, and it must not fail invisibly either.
    await openFresh(page);
    await uploadWorkbook(page, path.join(WORKBOOKS, 'ScheduleHub_v3.1_Starter.xlsx'));

    const overlay = page.locator(NATIVE_OVERLAY);
    await expect(overlay).toBeVisible({ timeout: 40_000 });
    await expect(overlay).toContainText('0');

    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect(overlay).toHaveCount(0);
    // Nothing real was created from an empty template.
    const projects = await page.evaluate(() => nsListCanonicalProjects());
    expect(projects).toEqual([]);
  });

  test('a workbook with a repeated row still imports, and reports what it saw', async ({ page }) => {
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-duplicate-rows.xlsx'));
    const overlay = page.locator(NATIVE_OVERLAY);
    await expect(overlay).toBeVisible({ timeout: 40_000 });
    // 42 real rows plus the one exact duplicate.
    await expect(overlay).toContainText('43');

    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect.poll(() => page.evaluate(() => nsListCanonicalProjects().length), { timeout: 30_000 }).toBeGreaterThan(0);
    // Merging is by stable ID, so the duplicate must not double-count.
    const schedule = await page.evaluate(() => nsListCanonicalProjects()[0].scheduleCount);
    expect(schedule).toBeLessThanOrEqual(43);
  });

  test('re-importing the identical workbook is refused rather than duplicated', async ({ page }) => {
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });
    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect.poll(() => page.evaluate(() => nsListCanonicalProjects().length), { timeout: 30_000 }).toBeGreaterThan(0);
    const before = await page.evaluate(() => nsListCanonicalProjects()[0].scheduleCount);

    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await page.waitForTimeout(6000);
    const after = await page.evaluate(() => nsListCanonicalProjects()[0].scheduleCount);
    expect(after).toBe(before);
  });
});

test.describe('import safety net', () => {
  test('a native import takes a restore point before it commits', async ({ page }) => {
    // Regression: the snapshot hook was originally added only to confirmParsePreview, which handles
    // general-roster workbooks. Every native SyncSheets format commits through
    // nsConfirmNativeImport instead, so the formats this product is built around were importing
    // with no way back.
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });
    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect.poll(() => page.evaluate(() => nsListCanonicalProjects().length), { timeout: 30_000 }).toBeGreaterThan(0);

    // nsConfirmNativeImport deliberately does not await the snapshot: its IndexedDB write settles
    // after the commit, and the index entry is only written once that put completes. Reading the
    // index the moment the projects appear races that write under load.
    await expect
      .poll(() => page.evaluate(() => nsListSnapshots().some((s) => s.reason === 'auto-import')), { timeout: 30_000 })
      .toBe(true);
  });

  test('the restore point holds the workspace as it was BEFORE the import', async ({ page }) => {
    // A snapshot taken after the merge would be worthless. Import once, then import a second
    // workbook and confirm the newest restore point still describes the first world.
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });
    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect.poll(() => page.evaluate(() => nsListCanonicalProjects().length), { timeout: 30_000 }).toBeGreaterThan(0);
    const afterFirst = await page.evaluate(() => nsListCanonicalProjects()[0].scheduleCount);

    await uploadWorkbook(page, generated('schedulehub-same-name-later-month.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });
    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect
      .poll(() => page.evaluate(() => nsListSnapshots().filter((s) => s.reason === 'auto-import').length), { timeout: 30_000 })
      .toBeGreaterThanOrEqual(2);

    const newest = await page.evaluate(() => nsListSnapshots().filter((s) => s.reason === 'auto-import')[0]);
    expect(newest.schedule).toBe(afterFirst);
  });

  test('restoring undoes an import', async ({ page }) => {
    await openFresh(page);
    await uploadWorkbook(page, generated('schedulehub-two-teams.xlsx'));
    await expect(page.locator(NATIVE_OVERLAY)).toBeVisible({ timeout: 40_000 });
    await page.locator(`${NATIVE_OVERLAY} button.primary`).click();
    await expect.poll(() => page.evaluate(() => nsListCanonicalProjects().length), { timeout: 30_000 }).toBeGreaterThan(0);

    // Wait for the restore point to land (see the first test in this block for why it is async).
    await expect
      .poll(() => page.evaluate(() => nsListSnapshots().some((s) => s.reason === 'auto-import')), { timeout: 30_000 })
      .toBe(true);
    const id = await page.evaluate(() => nsListSnapshots().find((s) => s.reason === 'auto-import').id);
    const result = await page.evaluate((snapId) => nsRestoreSnapshot(snapId), id);
    expect(result.ok).toBe(true);
    // Back to an empty workspace, which is what it was before the import.
    expect(await page.evaluate(() => nsListCanonicalProjects().length)).toBe(0);
  });
});
